import {NATIVE_UI} from './ui-catalog.js';
import {FEEDBACK_PACKS} from './feedback-catalog.js';
import {fetchWeaponAsset,weaponAssetURL} from './weapon-assets.js';
export const FEEDBACK_NAMES={auto:'随皮肤',sovereign:'天界神兵',phaseguard:'超时空护卫队',singularity:'奇点 · 白色',neo:'新边疆',additional:'资源包击杀徽章'};
export function setupNativeUI(doc){
 const mappings={touchFire:'attack',touchAim:'attack2',touchReload:'reload',touchJump:'jump',touchCrouch:'duck',touchSwitch:'lastinv',touchBuy:'buy',touchPlant:'use',touchPrimary:'1',touchPistol:'2',pauseBtn:'pause'};
 for(const[id,name]of Object.entries(mappings)){const file=NATIVE_UI.find(p=>p.endsWith('/buttons/'+name+'.png'));const el=doc.getElementById(id);if(el&&file){const img=doc.createElement('img');img.className='native-touch-icon';img.src=weaponAssetURL(file);img.alt='';el.prepend(img);}}
 const damage=NATIVE_UI.find(p=>p.endsWith('/damage_indicator.png'));if(damage)doc.getElementById('damage').style.backgroundImage=`url("${weaponAssetURL(damage)}")`;
 const banner=doc.getElementById('roundBanner');for(const result of ['won','lost']){const file=NATIVE_UI.find(p=>p.endsWith('/round_notice/'+result+'.png'));if(file)banner.style.setProperty('--native-'+result,`url("${weaponAssetURL(file)}")`);}
}
export class NativeFeedback{
 constructor(container,audio,volume){this.container=container;this.audio=audio;this.volume=volume;this.age=10;this.serial=0;this.cache=new Map();this.el=document.createElement('div');this.el.className='native-feedback hidden';container.append(this.el);}
 hide(){this.serial++;this.source?.stop();this.source=null;this.age=10;this.el.classList.add('hidden');this.container.classList.remove('native-pack-kill');}
 async play(family,count=1,head=false){this.hide();const pack=FEEDBACK_PACKS[family];if(!pack)return;this.family=family;this.count=Math.max(1,Math.min(5,count));this.head=head;this.age=0;this.el.classList.remove('hidden');this.container.classList.add('native-pack-kill');this.el.innerHTML=['bg','frame1','kill','icons','particles1','particles2'].map(l=>`<img data-native-layer="${l}" alt="">`).join('');this.update(0);const n=this.count,candidates=pack.sounds.filter(p=>new RegExp('(?:^|/)'+n+'\\.wav$','i').test(p)),file=candidates[0]||pack.sounds.find(p=>/kill/i.test(p));const ctx=this.audio();if(!ctx||!file)return;const serial=this.serial;try{if(!this.cache.has(file))this.cache.set(file,fetchWeaponAsset('./'+file).then(b=>ctx.decodeAudioData(b)).catch(e=>{this.cache.delete(file);throw e;}));const buffer=await this.cache.get(file);if(serial!==this.serial||this.age>2.2)return;const source=ctx.createBufferSource(),gain=ctx.createGain();source.buffer=buffer;gain.gain.value=this.volume();source.connect(gain);gain.connect(ctx.destination);source.start();this.source=source;}catch{}}
 update(dt){if(this.age>=2.2)return;this.age+=dt;const pack=FEEDBACK_PACKS[this.family];for(const[layer,name]of Object.entries({bg:'1',frame1:String(this.count),kill:String(this.count),icons:this.head?'headshot':'skull',particles1:String(Math.min(6,1+Math.floor(this.age*12))),particles2:String(Math.min(13,1+Math.floor(this.age*18)))})){const file=pack.images.find(p=>p.toLowerCase().endsWith('/'+layer+'/'+name+'.png'));const el=this.el.querySelector(`[data-native-layer="${layer}"]`);if(file&&el){const url=weaponAssetURL('./'+file);if(el.getAttribute('src')!==url)el.src=url;el.hidden=false;}else if(el)el.hidden=true;}this.el.style.opacity=this.age>1.65?Math.max(0,(2.2-this.age)/.55):1;if(this.age>=2.2)this.hide();}
}
